CREATE TABLE objects(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,bytes BLOB NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE import_messages(owner_id TEXT NOT NULL,provider TEXT NOT NULL,external_id TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,PRIMARY KEY(owner_id,provider,external_id));
CREATE TABLE preferences(owner_id TEXT PRIMARY KEY,embedding_connection TEXT REFERENCES connections(id),embedding_model TEXT,embedding_enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE search_documents(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,agent_id TEXT,conversation_id TEXT,folder_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX search_owner ON search_documents(owner_id,created_at);
CREATE VIRTUAL TABLE search_fts USING fts5(id UNINDEXED, owner_id UNINDEXED, title, content, tokenize='unicode61');
CREATE TABLE embeddings(document_id TEXT PRIMARY KEY REFERENCES search_documents(id) ON DELETE CASCADE,owner_id TEXT NOT NULL,model TEXT NOT NULL,vector TEXT NOT NULL,content_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TRIGGER search_insert AFTER INSERT ON search_documents BEGIN INSERT INTO search_fts VALUES(new.id,new.owner_id,new.title,new.content); END;
CREATE TRIGGER search_update AFTER UPDATE ON search_documents BEGIN DELETE FROM search_fts WHERE id=old.id; INSERT INTO search_fts VALUES(new.id,new.owner_id,new.title,new.content); END;
CREATE TRIGGER search_delete AFTER DELETE ON search_documents BEGIN DELETE FROM search_fts WHERE id=old.id; END;
CREATE TRIGGER message_search_insert AFTER INSERT ON messages BEGIN INSERT INTO search_documents SELECT 'message:'||new.id,new.owner_id,'message',substr(new.content,1,90),new.content,c.agent_id,new.conversation_id,NULL,new.created_at,new.created_at FROM conversations c WHERE c.id=new.conversation_id; END;
CREATE TRIGGER message_search_update AFTER UPDATE OF content ON messages BEGIN UPDATE search_documents SET content=new.content,title=substr(new.content,1,90),updated_at=unixepoch()*1000 WHERE id='message:'||new.id; DELETE FROM embeddings WHERE document_id='message:'||new.id; END;
CREATE TRIGGER message_search_delete AFTER DELETE ON messages BEGIN DELETE FROM search_documents WHERE id='message:'||old.id; END;
CREATE TRIGGER artifact_search_insert AFTER INSERT ON artifacts BEGIN INSERT INTO search_documents VALUES('artifact:'||new.id,new.owner_id,new.kind,new.title,new.content,new.agent_id,new.conversation_id,new.folder_id,new.created_at,new.updated_at); END;
CREATE TRIGGER artifact_search_update AFTER UPDATE ON artifacts BEGIN UPDATE search_documents SET title=new.title,content=new.content,folder_id=new.folder_id,kind=new.kind,updated_at=new.updated_at WHERE id='artifact:'||new.id; DELETE FROM embeddings WHERE document_id='artifact:'||new.id AND (old.content<>new.content OR old.title<>new.title); END;
CREATE TRIGGER artifact_search_delete AFTER DELETE ON artifacts BEGIN DELETE FROM search_documents WHERE id='artifact:'||old.id; END;
INSERT INTO search_documents SELECT 'message:'||m.id,m.owner_id,'message',substr(m.content,1,90),m.content,c.agent_id,m.conversation_id,NULL,m.created_at,m.created_at FROM messages m JOIN conversations c ON c.id=m.conversation_id;
INSERT INTO search_documents SELECT 'artifact:'||id,owner_id,kind,title,content,agent_id,conversation_id,folder_id,created_at,updated_at FROM artifacts;
INSERT INTO schema_version VALUES(3,unixepoch()*1000);
